function ActivityCatBallRescuePanel:Refresh(dojo)
    self._animMapList = {}
    self._itemShowNum = 0
    KTool.SetActive(self.ListView.gameObject, false)
    
    self._activityDojo = checkTable(dojo)
    print("->>>ActivityCatBallRescuePanel:Refresh__activityDojo:", table.dump(self._activityDojo))
    --- 任务列表
    self:GetServersData()
    --- 活动文本数据
    self.TxtDetail.text = checkString(self._activityDojo.detail)
    CfUtils.FillWebRawImage(self.ImgTitleName, checkString(self._activityDojo.titleImage))
   
    --- 活动时间
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self._activityDojo.startTime, self._activityDojo.endTime))
    self:ActivityCountDown()
    
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id234) -- 检查猫屋模块的解锁状态
    if checkBool(isUnlock) then
        --- 跳转入口
        SetButtonAction(self.BtnGo.gameObject, function()
            --Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
            if checkNumber(KCookie.Get(Constants.IsOpnePageing)) == 1 then return end
            KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, checkNumber(self._activityDojo.id))

            local countWait = 0
            local blackWait = true
            GameUtils.ShowBlackOverlay(nil, function()
                while blackWait and countWait <= 5 do
                    coroutine.yield(Yielders.GetWaitForSeconds(0.5))
                    countWait = countWait + 0.5
                end
            end)
            cs_coroutine.start(function()
                cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseMainDialog }, { { id = Constants.UITypeIds.UIActivityMainDialog } }))
                blackWait = false
            end)
        end)
    else
        SetButtonAction(self.BtnGo.gameObject,function() 
            GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id234))
        end)
    end
   
end

function ActivityCatBallRescuePanel:RefreshTaskStatus()
    
    local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", self._theme)
    self.TxtNameCat.text = checkString(catDataVo.name)
    
    KTool.SetActive(self.ListView.gameObject, true)
    if self.ListView.IsListViewInit then
        GameUtils.ReloadData(self.ListView, table.count(self._listTask))
    else
        self.ListView:InitListView(table.count(self._listTask), Bind(self, self.OnGetItemByIndex))
    end
    local numTaskFinished, numTotalTask = self:GetTaskProcess()
    self.TxtTaskProcess.text = string.format("%d/%d", numTaskFinished, numTotalTask)
    --- 更新奖励领取按钮状态
    self:RefreshBtnRewardStatus()
end


function ActivityCatBallRescuePanel:OnGetItemByIndex(gridView, index)
    if index < 0 then return end
    local cell = gridView:NewListViewItem(TaskNodePrefabPath)
    if not IsNull(cell) then
        local _lbCell = GetLuaBehaviour(cell.gameObject, TaskNodeLuaPath)
        if _lbCell then
            
            if isNull(_lbCell.Env) then _lbCell:Init() end
            local _ltCell = _lbCell.Env
            _ltCell:SetCellInfo(checkTable(self._listTask[checkInt(index + 1)]))
            
            if checkInt(self._itemShowNum) <= 0 then
                local cellSizeH  = cell.CachedRectTransform.rect.height + cell.Padding
                self._itemShowNum = math.ceil(gridView.ViewPortHeight / cellSizeH)
            end
            
            if not self._animMapList[index + 1] and index <= checkInt(self._itemShowNum) then
                self._animMapList[index + 1] = true
                _ltCell:PlayFadeInAnim(index)
            else
                _ltCell:PlayInitAnim()
            end
        end
    end
    return cell
end

function ActivityCatBallRescuePanel:GetNumTaskFinished()
    local numResult = 0
    local listTask = checkTable(self._listTask)
    for i, dataTask in pairs(listTask) do
        if dataTask.status == TaskFinishedStatus.Finished  then
            numResult = numResult + 1
        end
    end
    return numResult
end

function ActivityCatBallRescuePanel:GetTaskProcess()
    local _numTotalTask = table.count(self._listTask)
    local _numTaskFinished = self:GetNumTaskFinished()
    return checkInt(_numTaskFinished), checkInt(_numTotalTask)
end

function ActivityCatBallRescuePanel:ActionDrawReward()
    SetButtonAction(self.BtnReward.gameObject, nil)
    self._coShowDrawReward = cs_coroutine.start(function()
        self.BtnRewardAminRoot:Play(BtnRewardAminPath.Completed)
        if  self.BtnRewardAminRoot.isPlaying then
            cs_coroutine.yield_return()
        end
        self.BtnRewardAminRoot:Play(BtnRewardAminPath.CompletedLoop)
        self._coShowDrawReward = nil
    end)
    local activityUuid = checkInt(self._activityDojo.id)
    self:CatBallTaskRewardReq(activityUuid, function()
        self._rewardDrawnStatus = RewardDrawnStatusService.Drawn
        Events.Broadcast(Constants.EventNames.ActivityRedPointChange, checkNumber(self._activityDojo.id), -1)
        self:RefreshTaskStatus()
    end)
end

function ActivityCatBallRescuePanel:RefreshBtnRewardStatus()
    local drawnStatus = 0
    
    if self._rewardDrawnStatus == RewardDrawnStatusService.Drawn then
        drawnStatus = RewardDrawnStatus.Drawn
    elseif self._rewardDrawnStatus == RewardDrawnStatusService.NotDrawn then
        local numTaskFinished, numTotalTask = self:GetTaskProcess()
        drawnStatus =  numTaskFinished >= numTotalTask and RewardDrawnStatus.Finished or RewardDrawnStatus.InProgress
    end

    KTool.SetActive(self.ProgressNode.gameObject, drawnStatus == RewardDrawnStatus.InProgress)
    KTool.SetActive(self.AvailableNode.gameObject, drawnStatus == RewardDrawnStatus.Finished)
    KTool.SetActive(self.ReceivedNode.gameObject, drawnStatus == RewardDrawnStatus.Drawn)
    KTool.SetActive(self.UIFX_CatHouseMainBlindbox.gameObject, drawnStatus == RewardDrawnStatus.Finished)
    
    local _ActionBtnReward = function(status)
        local _listAction = {
            [RewardDrawnStatus.InProgress] = function()
                local goodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(self._rewards.goodsId))
                GameUtils.ShowCommonTipsBoard(self.BtnReward.gameObject, goodVo.name, goodVo.desc, goodVo.quality, goodVo.id)
            end,
            [RewardDrawnStatus.Finished] = function() self:ActionDrawReward() end,
            [RewardDrawnStatus.Drawn] = nil,
        }
        return _listAction[status]
    end
    
    SetButtonAction(self.BtnReward.gameObject, _ActionBtnReward(drawnStatus))

    xTry(function()
        if isNull(self._coShowDrawReward) then
            local _GetAmin = function(status)
                local name = ""
                if status == RewardDrawnStatus.InProgress or status == RewardDrawnStatus.Finished then
                    name = BtnRewardAminPath.Loop
                elseif  status == RewardDrawnStatus.Drawn then
                    name = BtnRewardAminPath.CompletedLoop
                end
                return name
            end
            if not isNull(self.BtnRewardAminRoot) then
                self.BtnRewardAminRoot:Play(checkString(_GetAmin(drawnStatus)))
            end
        end
    end)
end

function ActivityCatBallRescuePanel:GetServersData()
    local activityUuid = checkInt(self._activityDojo.id)
    self:CatBallTaskHomeReq(activityUuid, function() 
        self:RefreshTaskStatus()
    end)
end

function ActivityCatBallRescuePanel:CatBallTaskHomeReq(activityUuid, cb)
    GameUtils.Request(Interfaces.ActivityCatBallTaskHome, { activityUuid = activityUuid }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        print("->>>CatBallTaskHomeReq_response:", checkTable(response))
        local dataRep = checkTable(response.data)
        self._listTask = checkTable(dataRep.activityTask)
        self._rewardDrawnStatus =  checkNumber(dataRep.rewardStatus)
        self._theme = checkNumber(dataRep.theme)
        self._rewards = checkTable(checkTable(dataRep.reward)[1]) --奖励列表的第一个
        if cb then cb() end
    end)
end

function ActivityCatBallRescuePanel:CatBallTaskRewardReq(activityUuid, cb)
    GameUtils.Request(Interfaces.ActivityCatBallTaskReward, { activityUuid = activityUuid }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local dataRep = checkTable(response.data)
        local rewards = checkTable(dataRep.rewards)
        --rewards = { goodsId = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 15).num, num = 10 }
        if #checkTable(rewards) > 0 then
            GoodsUtils.DrawRewards(rewards)
        end
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        if cb then cb() end
    end)
end

function ActivityCatBallRescuePanel:ActivityCountDown()
    self:CleanCountdown()
    xTry(function() 
        local curTime = os.time()
        local transFather = self.TxtTimeLeft.transform.parent
        if not isNull(transFather) then
            local transTimeGroup = transFather.parent
            if not isNull(transTimeGroup) then
                KTool.SetActive(transTimeGroup.gameObject, checkNumber(curTime) < checkNumber(self._activityDojo.endTime))
            end
        end
        if checkNumber(curTime) < checkNumber(self._activityDojo.endTime) then
            local count = checkNumber(self._activityDojo.endTime - curTime)
            self._timer = CDTimerModule:AddCD(1, function(countTimes, timerId)
                CfUtils.FillText(self.TxtTimeLeft, CfUtils.GetTimeHMS3(countTimes, 28))
            end, count, true, true)
        end
    end)
end

function ActivityCatBallRescuePanel:CleanCountdown()
    if not isNull(self._timer) then
        CDTimerModule:RemoveCD(self._timer)
        self._timer = nil
    end
end

function ActivityCatBallRescuePanel:GetCatTaskConfigData(refId)
    local rowConfig = CfUtils.GetCfLine(AutoIds.IdSetting1919, refId)
    local dataTask = {
        desc = parse_string(rowConfig, "desc"),
        taskContenNum = parse_number(rowConfig, "taskContenNum")
    }
    return dataTask
end

return ActivityCatBallRescuePanel
